import os
import sys
import json
import pickle
import logging
import time
import numpy as np
import pandas as pd
from pathlib import Path

# Ensure parent directory is in path for imports if run directly
if 'code' not in sys.path:
    code_dir = Path(__file__).resolve().parent
    if code_dir.name == 'code':
        sys.path.insert(0, str(code_dir.parent))

from logging_config import get_module_logger

logger = get_module_logger(__name__)

def load_lmm_summary():
    """Load the LMM summary CSV generated by compute_trends.py."""
    path = Path('data/derived/lmm_summary.csv')
    if not path.exists():
        raise FileNotFoundError(f"LMM summary not found at {path}. Run T012b first.")
    return pd.read_csv(path)

def load_lrt_results():
    """Load the LRT results JSON generated by analyze_drift.py."""
    path = Path('data/derived/lrt_results.json')
    if not path.exists():
        raise FileNotFoundError(f"LRT results not found at {path}. Run T013 first.")
    with open(path, 'r') as f:
        return json.load(f)

def calculate_significance_at_alpha(p_value, alpha):
    """Determine if a p-value is significant at a given alpha level."""
    return p_value < alpha

def run_sensitivity_analysis():
    """
    Run sensitivity analysis sweeping alpha across {0.01, 0.05, 0.1}.
    Reports the drift significance rates.
    """
    lrt_results = load_lrt_results()
    p_value = lrt_results.get('p_value')
    
    if p_value is None:
        raise ValueError("p_value not found in LRT results.")

    alphas = [0.01, 0.05, 0.1]
    results = []
    
    for alpha in alphas:
        is_significant = calculate_significance_at_alpha(p_value, alpha)
        results.append({
            'alpha': alpha,
            'p_value': p_value,
            'is_significant': is_significant
        })
        logger.info(f"Alpha={alpha}: Significance={is_significant}")
    
    return results

def save_sensitivity_results(results):
    """Save sensitivity analysis results to JSON."""
    output_path = Path('results/sensitivity_analysis.json')
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, 'w') as f:
        json.dump(results, f, indent=2)
    logger.info(f"Sensitivity results saved to {output_path}")

def handle_convergence_failures(permutation_results):
    """
    Handle permutation convergence failures and flag results as "approximate".
    
    This function checks the status and iteration counts of the permutation test.
    If the test was terminated early (status='approximate') or failed to converge
    to a stable p-value within the iteration limit, it logs a warning and ensures
    the 'approximate' flag is set in the results dictionary.
    
    Args:
        permutation_results (dict): The results dictionary from run_permutation_test.
                                    Expected keys: 'iterations_run', 'status', 'p_value'.
    
    Returns:
        dict: The updated results dictionary with explicit 'approximate' flag if needed.
    """
    status = permutation_results.get('status', 'unknown')
    iterations_run = permutation_results.get('iterations_run', 0)
    target_iterations = permutation_results.get('target_iterations', 10000)
    
    is_approximate = False
    reason = ""

    if status == 'approximate':
        is_approximate = True
        reason = "Permutation test terminated early due to time/memory constraints."
    elif status == 'failed':
        is_approximate = True
        reason = "Permutation test failed to converge or encountered an error."
    elif iterations_run < target_iterations:
        is_approximate = True
        reason = f"Only {iterations_run} iterations completed, less than target {target_iterations}."

    if is_approximate:
        logger.warning(f"Convergence failure detected: {reason}. Flagging results as 'approximate'.")
        permutation_results['is_approximate'] = True
        permutation_results['convergence_reason'] = reason
    else:
        permutation_results['is_approximate'] = False
        logger.info("Permutation test converged successfully.")

    return permutation_results

def run_permutation_test(n_permutations=10000, timeout_seconds=14400):
    """
    Run a non-parametric permutation test to validate the drift coefficient.
    
    This function shuffles the 'year' labels to generate a null distribution
    of the drift slope. It includes logic to handle time limits and flag
    approximate results.
    
    Args:
        n_permutations (int): Target number of permutations.
        timeout_seconds (int): Maximum runtime in seconds (default 4 hours).
    
    Returns:
        dict: Permutation test results including p-value and status.
    """
    logger.info(f"Starting permutation test with target {n_permutations} iterations.")
    
    # Load data required for the test
    # We need the observed slope and the data to permute
    # Assuming we have the full dataset used for the LMM
    # For this implementation, we simulate the process of getting the slope
    # In a real run, this would load the specific data used in T012a/T013a
    
    # Placeholder for loading the actual data structure used in the model
    # This would typically come from a shared state or re-load the processed CSV
    try:
        df = pd.read_csv('data/derived/power_estimates.csv')
    except FileNotFoundError:
        logger.error("power_estimates.csv not found. Cannot run permutation test.")
        return {'status': 'failed', 'error': 'Data not found'}

    # Extract the observed slope (from T012b)
    lmm_summary = load_lmm_summary()
    observed_slope = lmm_summary.iloc[0]['slope_year']
    
    start_time = time.time()
    null_distribution = []
    iterations_run = 0
    status = 'exact'
    
    # Prepare data for permutation
    years = df['year'].values
    power_est = df['power_est'].values
    # We need to re-calculate the slope for each permutation
    # To keep it fast, we use a simple linear regression slope calculation
    # slope = cov(x, y) / var(x)
    # We permute x (years)
    
    mean_y = np.mean(power_est)
    var_x = np.var(years)
    
    if var_x == 0:
        logger.error("Zero variance in year. Cannot compute slope.")
        return {'status': 'failed', 'error': 'Zero variance in year'}

    for i in range(n_permutations):
        # Check timeout
        elapsed = time.time() - start_time
        if elapsed > timeout_seconds:
            status = 'approximate'
            logger.warning(f"Timeout reached at {elapsed:.1f}s. Stopping permutation test.")
            break
        
        # Shuffle years
        permuted_years = np.random.permutation(years)
        
        # Calculate slope for permuted data
        # slope = sum((x - mean_x) * (y - mean_y)) / sum((x - mean_x)^2)
        # Since we are permuting x, mean_x and var_x (denominator) remain the same
        # Numerator changes
        numerator = np.sum((permuted_years - np.mean(years)) * (power_est - mean_y))
        permuted_slope = numerator / (len(years) * var_x)
        
        null_distribution.append(permuted_slope)
        iterations_run += 1
      
      # Calculate empirical p-value
    null_distribution = np.array(null_distribution)
    # Two-tailed test: proportion of null slopes more extreme than observed
    # |slope| > |observed_slope|
    extreme_count = np.sum(np.abs(null_distribution) >= np.abs(observed_slope))
    p_value = extreme_count / iterations_run
    
    results = {
        'observed_slope': observed_slope,
        'p_value': p_value,
        'iterations_run': iterations_run,
        'target_iterations': n_permutations,
        'status': status,
        'null_distribution_stats': {
            'mean': float(np.mean(null_distribution)),
            'std': float(np.std(null_distribution))
        }
    }
    
    # Apply convergence failure handling
    results = handle_convergence_failures(results)
    
    return results

def main():
    """Main entry point for robustness checks."""
    logger.info("Running robustness checks (Permutation & Sensitivity).")
    
    # 1. Sensitivity Analysis
    try:
        sens_results = run_sensitivity_analysis()
        save_sensitivity_results(sens_results)
    except Exception as e:
        logger.error(f"Sensitivity analysis failed: {e}")
    
    # 2. Permutation Test
    try:
        perm_results = run_permutation_test()
        output_path = Path('results/permutation_pvalue.json')
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with open(output_path, 'w') as f:
            json.dump(perm_results, f, indent=2)
        logger.info(f"Permutation results saved to {output_path}")
    except Exception as e:
        logger.error(f"Permutation test failed: {e}")
    
    logger.info("Robustness checks complete.")

if __name__ == '__main__':
    main()